namespace PZ3D {
 static class SaveEnvironmentsTests {
  static int checks;static Type serviceType,recordType;static bool failPreparation;static Action<object> duringPreparation;
  static void Check(bool condition,string message){if(!condition)throw new Exception("FAIL "+message);checks++;}
  static void Put(string path,string value){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,value,new UTF8Encoding(false));}
  static object Field(object row,string name){return row.GetType().GetField(name).GetValue(row);}
  static string Text(object row,string name){return (string)Field(row,name);}
  static object Call(object service,string name,params object[] args){try{return serviceType.GetMethods().Single(method=>method.Name==name&&method.GetParameters().Length==args.Length).Invoke(service,args);}catch(TargetInvocationException error){throw error.InnerException;}}
  static object Static(string name,params object[] args){var method=serviceType.GetMethod(name,BindingFlags.Static|BindingFlags.Public|BindingFlags.NonPublic);Check(method!=null,"metadata ownership lookup exists without Engine construction");try{return method.Invoke(null,args);}catch(TargetInvocationException error){throw error.InnerException;}}
  static void Refuses(Action action,string reason){bool rejected=false;try{action();}catch(Exception){rejected=true;}Check(rejected,reason);}
  static object[] Rows(object list){return ((IEnumerable)list).Cast<object>().ToArray();}
  static void Prepare(object record){
   if(failPreparation)throw new IOException("Synthetic runtime preparation failure");
   Put(Path.Combine(Text(record,"RuntimeHome"),".zombie_buddy","config.json"),"{\"preload_mods\":{}}");
   Put(Path.Combine(Text(record,"GamePath"),"OrangeLauncherRuntime","startup","OrangeStartup.jar"),"pinned runtime");
   if(duringPreparation!=null)duringPreparation(record);
  }
  static Delegate Preparation(){return Delegate.CreateDelegate(typeof(Action<>).MakeGenericType(recordType),typeof(SaveEnvironmentsTests).GetMethod("Prepare",BindingFlags.Static|BindingFlags.NonPublic));}
  sealed class Fixture:IDisposable {
   internal readonly string Root,Game,User,Data,Save,First,Second;internal readonly Engine Engine;internal readonly object Service;
