    Root=Path.Combine(parent,name);Game=overlap==2?Path.Combine(Root,"user","Game"):Path.Combine(Root,"steamapps","common","ProjectZomboid");User=overlap==1?Path.Combine(Game,"User"):Path.Combine(Root,"user");Data=Path.Combine(Root,"data");Save=Path.Combine(User,"Saves","Sandbox","Original");
    Put(Path.Combine(Game,"ProjectZomboid64.exe"),"game binary");Put(Path.Combine(Game,"ProjectZomboid64.json"),"{\"vmArgs\":[]}");Put(Path.Combine(Game,"version.txt"),major==41?"41.78.16":"42.21.0");Put(Path.Combine(Game,"game-version.txt"),major==41?"41.78.16":"42.21.0");Put(Path.Combine(Game,"media","game.bin"),"game source bytes");Directory.CreateDirectory(Path.Combine(Game,"empty"));
    First=Path.Combine(Root,"steamapps","workshop","content","108600","100","mods","First");Second=Path.Combine(User,"mods","Second");
    string part=major==41?"":"42";
    Put(Path.Combine(First,part,"mod.info"),"id=First\nname=First\n");Put(Path.Combine(First,"common","media","texture.bin"),"common texture");Put(Path.Combine(First,"libs","plugin.jar"),"jar bytes");Put(Path.Combine(First,"libs","plugin.jar.zbs"),"signature bytes");
    Put(Path.Combine(Second,part,"mod.info"),"id=Second\nname=Second\nrequire=First\n");Put(Path.Combine(Second,part,"media","script.lua"),"return 'source'");
    Put(Path.Combine(User,"mods","default.txt"),"VERSION = 1,\nmods\n{\n mod = First,\n}\nmaps\n{\n}\n");
    Put(Path.Combine(Save,"mods.txt"),"VERSION = 1,\nmods\n{\n mod = First,\n mod = Second,\n}\nmaps\n{\n map = CustomMap,\n map = Muldraugh, KY,\n}\n");Put(Path.Combine(Save,"map.bin"),"original live world");
    Engine=new Engine(Game,User,Data,true,null,n=>new Process[0]);Service=Activator.CreateInstance(serviceType,BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic,null,new object[]{Engine},null);
   }
   internal object Preview(){return Call(Service,"Preview","Sandbox/Original");}
   internal object Create(string name="snapshot",Action<int,string> progress=null,CancellationToken? cancel=null){object plan=Preview();return Call(Service,"Create","Sandbox/Original",Path.Combine(Root,name),name,Text(plan,"stamp"),cancel??CancellationToken.None,progress,Preparation());}
   public void Dispose(){}
  }
  static Dictionary<string,byte[]> Tree(string root){return Directory.GetFiles(root,"*",SearchOption.AllDirectories).ToDictionary(p=>p.Substring(root.Length+1),File.ReadAllBytes,StringComparer.OrdinalIgnoreCase);}
  static bool EqualTree(Dictionary<string,byte[]> a,Dictionary<string,byte[]> b){return a.Count==b.Count&&a.All(p=>b.ContainsKey(p.Key)&&p.Value.SequenceEqual(b[p.Key]));}
  static void CopiesContentWithoutSaveMutation(string root){using(var f=new Fixture(root,"copy")){
   var saveBefore=Tree(f.Save);var preview=f.Preview();Check((bool)Field(preview,"ready")&&(int)Field(preview,"modCount")==2,"preview resolves every enabled mod source");Check((long)Field(preview,"gameBytes")>0&&(long)Field(preview,"modBytes")>0,"preview computes game and complete mod sizes");
   var phases=new List<string>();object record=f.Create("one",(v,t)=>phases.Add(t));string copied=Text(record,"GamePath");Check(File.ReadAllText(Path.Combine(copied,"media","game.bin"))=="game source bytes"&&Directory.Exists(Path.Combine(copied,"empty")),"full game and empty directories copied");
   Check(((string[])Field(record,"ModIds")).SequenceEqual(new[]{"First","Second"}),"captured save order is exact");Check(((string[])Field(record,"Maps")).SequenceEqual(new[]{"CustomMap","Muldraugh, KY"}),"captured map order is exact");
   object[] mappings=Rows(Field(record,"ModRoots"));string firstCopy=Text(mappings.Single(m=>Text(m,"SourceRoot")==f.First),"CopiedRoot");Check(File.ReadAllText(Path.Combine(firstCopy,"common","media","texture.bin"))=="common texture"&&File.ReadAllText(Path.Combine(firstCopy,"libs","plugin.jar.zbs"))=="signature bytes","whole source root preserves common assets Java libraries and signatures");
   Check(Path.GetFileName(firstCopy)=="First"&&Directory.GetParent(firstCopy).Name=="mods"&&Directory.GetParent(Directory.GetParent(firstCopy).FullName).Parent.FullName==Path.Combine(Text(record,"RootPath"),"mods"),"copied mod keeps original root name inside independent item/mods wrapper");
   Check(EqualTree(saveBefore,Tree(f.Save)),"snapshot creation leaves original save byte-identical");Check(!Directory.Exists(Path.Combine(f.Data,"save-backups"))&&!Directory.GetFiles(f.Root,"*.zip",SearchOption.AllDirectories).Any(),"creation never produces an automatic save archive");
   int gamePhase=phases.FindIndex(s=>s.StartsWith("复制游戏",StringComparison.Ordinal)),modPhase=phases.FindIndex(s=>s.StartsWith("复制模组",StringComparison.Ordinal));Check(gamePhase>=0&&modPhase>gamePhase,"game copy precedes mod copy");
   string id=Text(record,"Id");Directory.Delete(f.Game,true);Directory.Delete(f.First,true);Directory.Delete(f.Second,true);
   object loaded=Call(f.Service,"Get",id);Check(Text(loaded,"Id")==id&&Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==id,"metadata and binding remain readable after source deletion");Check(File.ReadAllText(Path.Combine(Text(loaded,"GamePath"),"media","game.bin"))=="game source bytes"&&File.ReadAllText(Path.Combine(firstCopy,"libs","plugin.jar"))=="jar bytes","deleting sources cannot change independent snapshot files");
   Check(Text(Static("FindOwned",f.Data,Text(record,"GamePath"),f.User),"Id")==id&&(bool)Static("OwnsUser",f.Data,Text(record,"GamePath"),f.User),"worker ownership accepts exact registered game and original live user after source deletion");Check(Static("FindOwned",f.Data,f.Game,f.User)==null&&!(bool)Static("OwnsUser",f.Data,Text(record,"GamePath"),Path.Combine(f.Root,"foreign-user")),"ordinary games and foreign user aliases are not snapshot ownership");
   Put(Path.Combine(Text(record,"RuntimeHome"),".zombie_buddy","config.json"),"runtime changed");Check(Call(f.Service,"Get",id)!=null,"mutable runtime state is outside immutable payload hash");
   Refuses(()=>Call(f.Service,"Bind","Sandbox/Other",id,Text(loaded,"Stamp")),"binding refuses a different original save");
  }}
  static void PreservesOriginalListsDespiteAuthorMetadata(string root){foreach(string kind in new[]{"reverse","conflict","cycle","implicit"})using(var f=new Fixture(root,"original-"+kind)){
   string order=kind=="implicit"?" mod = Second,\n":" mod = Second,\n mod = First,\n";
   Put(Path.Combine(f.Save,"mods.txt"),"VERSION = 1,\nmods\n{\n"+order+"}\nmaps\n{\n}\n");
   Put(Path.Combine(f.User,"mods","default.txt"),"VERSION = 1,\nmods\n{\n mod = Second,\n}\nmaps\n{\n}\n");
   if(kind=="conflict")Put(Path.Combine(f.First,"42","mod.info"),"id=First\nname=First\nincompatible=Second\n");
   if(kind=="cycle")Put(Path.Combine(f.First,"42","mod.info"),"id=First\nname=First\nrequire=Second\n");
   var before=Tree(f.Save);byte[] defaults=File.ReadAllBytes(Path.Combine(f.User,"mods","default.txt"));var plan=f.Preview();
   Check((bool)Field(plan,"ready"),kind+" author metadata must not block original file capture: "+string.Join(";",(string[])Field(plan,"warnings")));
   Check((long)Field(plan,"gameBytes")>0&&(long)Field(plan,"modBytes")>0,kind+" measures available files");
   Check(((string[])Field(plan,"warnings")).Length==0,kind+" does not display author order/conflict warnings");
   var record=f.Create();Check(((string[])Field(record,"ModIds")).SequenceEqual(kind=="implicit"?new[]{"Second"}:new[]{"Second","First"}),kind+" keeps explicit save list");
   Check(((string[])Field(record,"DefaultModIds")).SequenceEqual(new[]{"Second"}),kind+" does not enable supplemental dependency");
   Check(EqualTree(before,Tree(f.Save))&&defaults.SequenceEqual(File.ReadAllBytes(Path.Combine(f.User,"mods","default.txt"))),kind+" preserves source bytes");
  }}
  static void RetainsAndRebinds(string root){using(var f=new Fixture(root,"retention")){
   object first=f.Create("one");string firstId=Text(first,"Id");Put(Path.Combine(f.Game,"media","game.bin"),"new game version bytes");Put(Path.Combine(f.Second,"42","media","script.lua"),"new mod bytes");
   object updates=Call(f.Service,"CheckUpdates",firstId);Check((bool)Field(updates,"available")&&(bool)Field(updates,"changed"),"explicit check detects changed game or mod sources");
   object second=f.Create("two");Check(Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==Text(second,"Id"),"successful new snapshot becomes bound");Check(Rows(Call(f.Service,"List","Sandbox/Original")).Length==2&&Directory.Exists(Text(first,"RootPath")),"old working snapshot is retained");
   object latestFirst=Call(f.Service,"Get",firstId);Call(f.Service,"Bind","Sandbox/Original",firstId,Text(latestFirst,"Stamp"));Check(Text(Call(f.Service,"Bound","Sandbox/Original"),"Id")==firstId,"explicit switch can return to old snapshot");Refuses(()=>Call(f.Service,"Bind","Sandbox/Original",Text(second,"Id"),Text(latestFirst,"Stamp")),"stale binding stamp cannot overwrite a later selection");
  }}
  static void StartupMutableFilesDoNotSignalUpdates(string root){using(var f=new Fixture(root,"noise")){
   string startup=Path.Combine(f.Game,"OrangeLauncherRuntime","startup");string[] mutable={"session.properties","issues.txt","ownership.json"};foreach(string name in mutable)Put(Path.Combine(startup,name),"first mutable "+name);string jar=Path.Combine(startup,"OrangeStartup.jar");Put(jar,"original startup JAR");duringPreparation=record=>{foreach(string name in mutable)Put(Path.Combine(startup,name),"changed during preparation "+name);};object snapshot;try{snapshot=f.Create();}finally{duringPreparation=null;}string id=Text(snapshot,"Id");Check(!Rows(Field(snapshot,"GameSourceFiles")).Any(file=>mutable.Any(name=>Text(file,"Path")=="OrangeLauncherRuntime/startup/"+name)),"source capture excludes exactly the three mutable startup state files");Check(mutable.All(name=>!File.Exists(Path.Combine(Text(snapshot,"GamePath"),"OrangeLauncherRuntime","startup",name))),"copy does not carry stale startup session, issue or ownership files");
   foreach(string name in mutable){Put(Path.Combine(startup,name),"another launch changed "+name);var updates=Call(f.Service,"CheckUpdates",id);Check((bool)Field(updates,"available")&&!(bool)Field(updates,"gameChanged")&&!(bool)Field(updates,"changed"),"mutable startup "+name+" changes do not signal a game update");}
   foreach(string path in new[]{jar,Path.Combine(f.Game,"ProjectZomboid64.json"),Path.Combine(f.Game,"media","game.bin")}){byte[] before=File.ReadAllBytes(path);DateTime written=File.GetLastWriteTimeUtc(path);Put(path,path.EndsWith(".json",StringComparison.OrdinalIgnoreCase)?"{\"vmArgs\":[\"-Xmx5g\"]}":"real changed payload");var updates=Call(f.Service,"CheckUpdates",id);Check((bool)Field(updates,"available")&&(bool)Field(updates,"gameChanged"),"startup JAR, launch JSON and real game content each remain update evidence: "+Path.GetFileName(path));File.WriteAllBytes(path,before);File.SetLastWriteTimeUtc(path,written);}
