  static void PreviewReportsInventoryAndCanCancel(string root){using(var f=new Fixture(root,"preview-progress")){
   var overload=serviceType.GetMethods().SingleOrDefault(method=>method.Name=="Preview"&&method.GetParameters().Length==3);Check(overload!=null,"preview exposes cancellable real inventory progress");
   var progressType=typeof(Engine).Assembly.GetType("PZ3D.SaveEnvironmentProgress");Check(progressType!=null,"preview progress reports stage and measured counts");
   var observations=new List<object>();Action<object> observe=row=>observations.Add(row);var callback=Delegate.CreateDelegate(typeof(Action<>).MakeGenericType(progressType),observe.Target,observe.Method);var plan=overload.Invoke(f.Service,new object[]{"Sandbox/Original",CancellationToken.None,callback});
   Check((bool)Field(plan,"ready")&&observations.Any(row=>Text(row,"stage")=="game-inventory"&&(long)Field(row,"completedBytes")>0),"preview publishes discovered game bytes while sizing");
   Check(observations.All(row=>(long)Field(row,"totalBytes")>0||(int)Field(row,"value")==-1),"inventory never invents a percentage before a denominator exists");
   Check((long)Field(observations.Last(row=>Text(row,"stage")=="mod-catalog"),"completedFiles")==2,"catalog progress counts the two metadata files read, excluding directory probes and duplicate checkpoints");
   using(var cancellation=new CancellationTokenSource()){Action<object> stop=row=>{if(Text(row,"stage")=="mod-catalog")cancellation.Cancel();};var cancelCallback=Delegate.CreateDelegate(typeof(Action<>).MakeGenericType(progressType),stop.Target,stop.Method);Exception failure=null;try{overload.Invoke(f.Service,new object[]{"Sandbox/Original",cancellation.Token,cancelCallback});}catch(TargetInvocationException error){failure=error.InnerException;}Check(failure is OperationCanceledException,"preview cancellation interrupts catalog work before game inventory");}
  }}
  static void MissingDiagnosticsListEveryIdentity(string root){LegacyCacheInventoryDoesNotInventUpdates(root);NestedWorkshopCacheIsNotGamePayload(root);CreationPermitsReadOnlySourceClient(root);PreparationRefreshesOldSourcePreview(root);UserChoicesCarryIntoSnapshot(root);SearchesAndDownloadsMissingInSameCreate(root);using(var f=new Fixture(root,"missing-diagnostics")){
